t.script:
document.getElementById('searchRepuestos').addEventListener('keyup', function() {
    const searchValue = this.value;
    fetch('/alquiler/repuestos/' +  + '?search=' + encodeURIComponent(searchValue), {
        headers: {
            'X-Requested-With': 'XMLHttpRequest'
        }
    })
    .then(response => response.json())
    .then(data => {
        const tbody = document.querySelector('table tbody');
        tbody.innerHTML = ''; // Limpiar las filas existentes
        data.forEach(repuesto => {
            const row = `

                ${repuesto.fecha}
                ${repuesto.pedido}
                ${repuesto.descripcion}
                ${repuesto.cantidad}
                ${repuesto.contometro_ultimo}
                ${repuesto.contometro_actual}
                ${repuesto.rendimiento}
                ${repuesto.solicitante}
            `;
            tbody.innerHTML += row; // Agregar fila a la tabla
        });
    });
});
